'use client'

import React, { useState,useEffect } from 'react';
import { PayPalScriptProvider, PayPalButtons } from '@paypal/react-paypal-js';
import { doc, setDoc, addDoc, collection } from 'firebase/firestore';
import { db } from '../FirebaseConfig';
import { PaymentElement, useStripe, useElements, Elements} from '@stripe/react-stripe-js';
import '../styles/checkout.css';
import { Link } from 'react-router-dom';
import { loadStripe } from '@stripe/stripe-js';

// Initialize Stripe with your public key
// Load Stripe outside the component so it is not recreated on each render
const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_KEY_OPTION_TWO);
const Checkout = ({
  name: initialName,
  address: initialAddress,
  email,
  totalPrice,
  items = [],
  onClose,
  phone: initialPhone,
  clearCart,
}) => {
  const [selectedMethod, setSelectedMethod] = useState('PayPal');
  const [orderType, setOrderType] = useState('Bestellungen'); // Delivery or Pickup
  const [clientSecret, setClientSecret] = useState('');
  // Stripe hooks

  // Editable user information
  const [name, setName] = useState(initialName || '');
  const [address, setAddress] = useState(initialAddress || '');
  const [phone, setPhone] = useState(initialPhone || '');
   
  useEffect(() => {
    const fetchClientSecret = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_SERVER_URL}/create-payment-intent`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            amount: totalPrice * 100, // Stripe requires the amount in cents
            currency: "eur", // Replace "eur" with dynamic currency if needed
          }),
        });
  
        const data = await response.json();
  
        if (response.ok) {
          setClientSecret(data.clientSecret); // Set clientSecret for Stripe Elements
        } else {
          alert("Could not initialize payment. Please try again.");
        }
      } catch (error) {
        alert("An error occurred while initializing the payment.");
      }
    };
  
    if (totalPrice) {
      fetchClientSecret(); // Call the function when totalPrice is defined
    }
  },[totalPrice]); // Rerun this effect if totalPrice changes
  const validateUserDetails = () => {
    if (!name || !address || !phone) {
      alert('Please fill in all required fields: name, address, and phone.');
      return false;
    }
    return true;
  };




const handleOrderSuccess = async (details) => {
  const now = new Date();
  const orderData = {
      name,
      address,
      phone,
      email,
      totalPrice,
      paymentMethod: selectedMethod,
      orderType,
      items,
      createdAt: now,
  };

  const collectionName = orderType === "Bestellungen" ? "Bestellungen" : "Abholungen";
  const ordersCollectionRef = collection(db, collectionName);

  try {
      if (details.id) {
          const orderRef = doc(ordersCollectionRef, details.id);
          await setDoc(orderRef, orderData);
      } else {
          await addDoc(ordersCollectionRef, orderData);
      }

      alert("Order successfully placed!");
      clearCart();
      onClose();
  } catch (error) {
      alert("An error occurred while placing the order. Please try again.");
  }
};

  const handleCashPayment = () => {
    if (!validateUserDetails()) return;
    handleOrderSuccess({}); // Static ID for cash payments
  };

  return (
    <div className="checkout-modal">
      <div className="checkout-content">
        <h2>Checkout</h2>

        <div className="items-list">
          <h3>Items you're purchasing:</h3>
          <ul>
            {items.map((item, index) => (
              <li key={index}>
                {item.name} - €{parseFloat(item.price.replace('€', '').replace(',', '.')).toFixed(2)} (x{item.quantity})
              </li>
            ))}
          </ul>
        </div>

        <div className="user-information">
          <h3>User Information</h3>
          <label>Name: <input type="text" value={name} onChange={(e) => setName(e.target.value)} /></label>
          <label>Address: <input type="text" value={address} onChange={(e) => setAddress(e.target.value)} /></label>
          <label>Phone: <input type="number" value={phone} onChange={(e) => setPhone(e.target.value)} /></label>
          <p>Configure your information on <Link to={'/user'}>User</Link></p>
        </div>

        <div className="order-type">
          <label><input type="radio" value="Bestellungen" checked={orderType === 'Bestellungen'} onChange={() => setOrderType('Bestellungen')} /> Delivery</label>
          <label><input type="radio" value="Abholungen" checked={orderType === 'Abholungen'} onChange={() => setOrderType('Abholungen')} /> Pickup</label>
        </div>

        <p><strong>Total Price:</strong> €{totalPrice}</p>

        <div className="payment-methods">
        <h3>Select Payment Method:</h3>
  <select value={selectedMethod} onChange={(e) => setSelectedMethod(e.target.value)}>
    <option value="PayPal">PayPal</option>
    <option value="CreditCard">Credit Card</option>
    <option value="Cash">Cash on Delivery</option>
  </select>
        </div>

        {selectedMethod === 'PayPal' && (
           <div className="paypal-container">
               <PayPalScriptProvider options={{ "client-id": process.env.REACT_APP_PAYPAL_CLIENT_ID }}>
               <PayPalButtons
  createOrder={async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_SERVER_URL}/Paypal-Payment`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          amount: totalPrice.toString(),
          currency: "USD",  // Ensure the currency is passed as USD or EUR depending on your setup
          description: "Order Payment",
        }),
      });

      const data = await response.json();

      if (response.ok && data.orderID) {
        return data.orderID;  // Return the order ID for PayPal
      } else {
        throw new Error("Could not create PayPal order.");
      }
    } catch (error) {
      throw error;
    }
  }}
  onApprove={async (data, actions) => {
    try {
      // Capture the order using actions.order.capture() instead of data.order.capture()
      const details = await actions.order.capture();  // Correct way to capture payment
      await handleOrderSuccess(details);  // Handle order success
      alert("Payment successful!");
    } catch (error) {
      alert("An error occurred while processing the payment.");
    }
  }}
  onCancel={() => alert("Payment cancelled.")}
  onError={(err) => {
    alert("An error occurred during the payment process.");
  }}
/>
    </PayPalScriptProvider>
           </div>
        )}

        {selectedMethod === 'CreditCard' &&  (
            <div className="stripe-container">
                {clientSecret ? (
        <div className="stripe-container">
          <Elements stripe={stripePromise} options={{ clientSecret }}>
            <PaymentForm handleOrderSuccess={handleOrderSuccess}/>
          </Elements>
        </div>
      ) : (
        <p>Loading payment options...</p>
      )}
            </div>
        )}

        {selectedMethod === 'Cash' && <button className='cash' onClick={handleCashPayment}>Bestellen</button>}

        <button className='shut' onClick={onClose}>Close</button>
      </div>
    </div>
  );
};

// Payment Form Component
const PaymentForm = ({handleOrderSuccess}) => {
  const stripe = useStripe(); // Access Stripe instance
  const elements = useElements(); // Access Elements instance
  const [isProcessing, setIsProcessing] = useState(false);

  const handleConfirmPayment = async () => {
    if (!stripe || !elements) {
      return;
    }

    setIsProcessing(true);

    try {
      const { error, paymentIntent } = await stripe.confirmPayment({
        elements,
        redirect: 'if_required', // Automatically handle redirection if needed
      });

      if (error) {
        alert(`Payment failed: ${error.message}`);
      } else if (paymentIntent && paymentIntent.status === "succeeded") {
        alert("Payment successful!");
        handleOrderSuccess(paymentIntent);
      }
    } catch (error) {
      alert("An error occurred while confirming the payment.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="stripe-container">
      <PaymentElement />
      <button onClick={handleConfirmPayment} disabled={isProcessing}>
        {isProcessing ? "Processing..." : "Bezahlen"}
      </button>
    </div>
  );
};


export default Checkout;
