import React, { useState, useEffect, useContext } from 'react';
import { CartContext } from './CartContext'; // Import the Cart Context
import '../styles/menu.css';
import { ref, getDownloadURL, listAll } from 'firebase/storage';
import { storage } from '../FirebaseConfig';
import LazyLoad from 'react-lazyload';

export default function Menu() {
    const { addToCart, removeFromCart, cart } = useContext(CartContext);
    const [selectedCategory, setSelectedCategory] = useState(null);
    const [menu, setMenu] = useState({});
    const [loadingMenu, setLoadingMenu] = useState(true);

    // Fetch menu and images from Firebase storage
    useEffect(() => {
        const fetchMenuFileContent = async (fileName) => {
            try {
                const fileRef = ref(storage, `Menu/${fileName}`);
                const url = await getDownloadURL(fileRef);
                const response = await fetch(url);
                const data = await response.json();
                return { category: fileName.split('.')[0], items: data }; // Organize by category
            } catch (error) {
                console.error(`Error fetching content of ${fileName}:`, error);
            }
        };

        const fetchMenuFileNames = async () => {
            try {
                const menuRef = ref(storage, 'Menu/');
                const menuList = await listAll(menuRef);
                return menuList.items.map(itemRef => itemRef.name);
            } catch (error) {
                console.error('Error fetching menu file names:', error);
            }
        };
        const fetchImage = async (category, itemId) => {
            const cachedImage = localStorage.getItem(`${category}-${itemId}`);
            if (cachedImage) {
                return cachedImage;
            }
        
            const imageFormats = ['.jpg', '.jpeg', '.png', '.webp', '.gif'];
            for (const format of imageFormats) {
                try {
                    const imageRef = ref(storage, `Media/${category}/${itemId}${format}`);
                    const url = await getDownloadURL(imageRef);
                    localStorage.setItem(`${category}-${itemId}`, url); // Cache image URL
                    return url;
                } catch (error) {
                    console.warn(`Error fetching image ${itemId}${format}:`, error);
                }
            }
            return '';
        };

        const fetchMenu = async () => {
            try {
                const fileNames = await fetchMenuFileNames();
                const menuDataArray = await Promise.all(fileNames.map(fetchMenuFileContent));
        
                // Construct menu object
                const menuData = menuDataArray.reduce((acc, { category, items }) => {
                    acc[category] = items;
                    return acc;
                }, {});
        
                setMenu(menuData);
        
                // Pre-fetch all images concurrently after setting the menu
                const imagePromises = menuDataArray.map(({ category, items }) =>
                    items.map(item => fetchImage(category, item.id).then(imageUrl => item.imageUrl = imageUrl))
                );
        
                await Promise.all(imagePromises.flat());
        
                setLoadingMenu(false);
        
                if (!selectedCategory && Object.keys(menuData).length > 0) {
                    setSelectedCategory(Object.keys(menuData)[0]);
                }
            } catch (error) {
                console.error('Error fetching menu:', error);
            }
        };
        const fetchSelectedCategory = async () => {
            if (selectedCategory) {
                setLoadingMenu(true);
                const fileName = `${selectedCategory}.json`; // Assume categories are in separate files
                const { items } = await fetchMenuFileContent(fileName);
    
                const imagePromises = items.map(item =>
                    fetchImage(selectedCategory, item.id).then(imageUrl => item.imageUrl = imageUrl)
                );
                await Promise.all(imagePromises);
    
                setMenu(prevMenu => ({ ...prevMenu, [selectedCategory]: items }));
                setLoadingMenu(false);
            }
        };
    
        fetchSelectedCategory();

        fetchMenu(); // Call the fetch menu function
    }, [selectedCategory]);

    return (
        <div id="menu" className="menu_Container products">
            {loadingMenu ? (
                <p>Loading Menu...</p>
            ) : (
                <>
                    <div className="category-buttons">
                        {Object.keys(menu).map((category) => (
                            <button
                                key={category}
                                onClick={() => setSelectedCategory(category)}
                                className={`category-button ${selectedCategory === category ? 'active' : ''}`}
                            >
                                {category}
                            </button>
                        ))}
                    </div>

                    {selectedCategory && (
                        <div className="menu-items">
                            {menu[selectedCategory]?.map((item) => (
                                <div key={item.name} className="menu-item">
                                    <LazyLoad height={200} offset={100} >
                                    <img src={item.imageUrl} alt={item.name} className="menu-item-image" />
                                    </LazyLoad>
                                    <span>{item.name}</span>
                                    <span className='ingredient'>{item.ingredients}</span>
                                    <p>{item.price}</p>
                                    <button className='reducer' onClick={() => removeFromCart(item.name)}>-</button>
                                    <p>{cart[item.name]?.quantity || 0}</p>
                                    <button className="adder" onClick={() => addToCart(item)}>+</button>
                                </div>
                            ))}
                        </div>
                    )}
                </>
            )}
        </div>
    );
}
