import React, { useContext, useState,useEffect } from 'react';
import { CartContext } from './CartContext';
import Checkout from './Checkout'; // Import the Checkout component
import '../styles/basket.css';
import Bucket from '../trolley.png';
import { Elements } from '@stripe/react-stripe-js';
import {auth,db} from '../FirebaseConfig';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { loadStripe } from '@stripe/stripe-js';

// Load Stripe outside the component so it is not recreated on each render
const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_KEY_OPTION_TWO);

const Basket = () => {
    const { cart, getTotalPrice, removeFromCart,clearCart,totalPrice } = useContext(CartContext); // Get cart data from context
    //get User Informations

    const [showCheckout, setShowCheckout] = useState(false); // State to show or hide the checkout modal
     const [user,setUser] = useState([]);
    // Filter out invalid items to avoid null or undefined errors
    const validCartItems = Object.values(cart).filter(
        item => item && item.quantity && item.price
    );
    // Fetch Stripe Client Secret

    // Firebase Authentication State Listener
    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (user) => {
            if (user) {
                const userRef = doc(db, "users", user.uid);
                const userDoc = await getDoc(userRef);
                if (userDoc.exists()) {
                    setUser(userDoc.data());
                }
            } else {
                setUser({});
            }
        });

        return () => unsubscribe(); // Cleanup listener on unmount
    }, []);

    const handlePayClick = () => {
        setShowCheckout(true);
    };

    return (
        <div className='cart'>
            <h2 className='ti'>Your Basket</h2>
            {validCartItems.length ? (
                <ul className='liste'>
                    {validCartItems.map(item => (
                        <li key={item.name} className='pro'>
                            {item.name} x {item.quantity} - €{(item.quantity * parseFloat(item.price.replace('€', '').replace(',', '.'))).toFixed(2)}
                            <button className='re' onClick={() => removeFromCart(item.name)}>-</button> {/* Add button */}
                        </li>
                    ))}
                </ul>
            ) : (
                <>
                    <p className="Emty">Your basket is empty</p>
                    <img alt='Empty' src={Bucket} />
                </>
            )}
            <h3>Total Price: €{getTotalPrice()}</h3>
            {validCartItems.length > 0 && (
                <button className='pay' onClick={handlePayClick}>Pay</button>
            )}
            {/* Show Checkout Popup */}
            {showCheckout && (
                <Elements stripe={stripePromise}>
                      <Checkout 
                           name={user.name|| ''} // You can pass user details here
                            address={user.address|| ''}
                            email={user.email|| ''}
                            phone={user.phone || ''}
                            totalPrice={getTotalPrice()}
                            items={validCartItems} // Pass the valid cart items array
                            onClose={() => setShowCheckout(false)} // Close checkout modal
                            clearCart={clearCart}
                        />
                </Elements>
            )}
        </div>
    );
};

export default Basket;
