import React, { useState, useEffect,useContext} from 'react';
import './App.css';
import { db, storage, auth } from './FirebaseConfig';
import { collection, getDocs } from 'firebase/firestore';
import { ref, getDownloadURL } from 'firebase/storage';
import { HashRouter as Router, Route, Routes, Link } from 'react-router-dom';
import Home from './components/Home';
import Menu from './components/Menu';
import News from './components/News';
import UserProvider from './components/User';
import Contact from './components/Contact';
import Basket from './components/Basket';
import { CartContext } from './components/CartContext';
import Loger from "./icons/loger.png";
import Cart from "./trolley.png";
import { Navigate} from 'react-router-dom';

function App() {
  const [logoUrl, setLogoUrl] = useState('');
  const [number,setNumber] = useState('');
  const {totalItemCount} = useContext(CartContext);
  const [menuOpen, setMenuOpen] = useState(false);

  // Toggle menu visibility
  const toggleMenu = () => {
    setMenuOpen(prevMenuOpen => !prevMenuOpen); // Toggle menu state
  };
  useEffect(() => {

    const fetchNumber = async () => {
      try {
        const statusSnapshot = await getDocs(collection(db, 'StoreInformations'));
        if (!statusSnapshot.empty) {
          statusSnapshot.forEach(sta => {
            const phoneNumber = sta.data().phone;
            setNumber(phoneNumber); // Assuming setStatus is the setter for storing the number
          });
        } else {
          setNumber('+49 511 22868085');
        }
      } catch (err) {
        console.error("Error fetching phone number", err);
      }
    };
    const fetchLogoUrl = async () => {
      try {
        const logoRef = ref(storage, 'Logos/store.jpg'); // Adjust the path as needed
        const url = await getDownloadURL(logoRef);
        setLogoUrl(url);
      } catch (error) {
        console.error('Error fetching logo URL:', error);
      }
    };
    fetchNumber();
    fetchLogoUrl();
  }, []);
    // This will allow calling the store
    const callStore = () => {
      if (number) {
        window.location.href = `tel:${number}`; // Initiate a call on mobile devices
      } else {
        alert("Phone number is not available.");
      }
    };
    //Updating Amount

  // Function to toggle login form visibility
  return (
    <Router>
      <div className="App">
        <header className="App-header">
          {logoUrl ? (
            <Link to="/" style={{color: '#000000',fontFamily: 'monospace'}}><img className="logo" src={logoUrl} alt="Logo" /></Link>
          ) : (
            <p style={{fontFamily: 'sans-serif', fontSize: '40px',color: '#000000'}}>Tuna cafe + bistro ug </p>
          )}
          <nav className="navigator">
          <div className="burger" onClick={toggleMenu}>
  {menuOpen ? '✕' : '☰'} {/* Conditionally render X or Burger */}
</div>
            <ul className={`pages ${menuOpen ? 'active' : ''}`}>
              <li translate='no'><Link to="/" style={{ color: '#E5A20B', fontFamily: 'Bungee Spice',textDecoration: 'none' }} translate='no' onClick={toggleMenu}>Home</Link></li>
              <li><Link to="/menu" style={{ color: '#E5A20B', fontFamily: 'Bungee Spice',textDecoration: 'none' }} onClick={toggleMenu}>Menu</Link></li>
              <li><Link to="/news" style={{ color: '#E5A20B', fontFamily: 'Bungee Spice',textDecoration: 'none' }} onClick={toggleMenu}>App</Link></li>
              <li><Link to="/contact" style={{ color: '#E5A20B', fontFamily: 'Bungee Spice',textDecoration: 'none' }} onClick={toggleMenu}>Contact</Link></li>
            </ul>
            {/* Burger icon */}
          </nav>

          {/* User Icon */}
          <span
            className='user'
          >
             <Link to="/basket" className='userAcess'><img alt="Basket" className='basket' src={Cart}/><div className='amount'>{totalItemCount}</div> </Link>
                <Link to="/user" className='userAcess'><img alt="Loger" src={Loger} className='userInfos'/></Link>
          </span>
        </header>
        <main className="main">
          <Routes>
            <Route exact path="/" element={<Home Number={number} logo={logoUrl}/>}/>
            <Route path="/menu" element={<Menu/>} />
            <Route path="/news" element={<News />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/user" element={<UserProvider />} />
            <Route path="/basket" element={<Basket/>} />
            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        </main>
        <div className="call" onClick={callStore}>
        <svg  xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="50" height="50" fill="currentColor">
  <path d="M6.62 10.79a15.05 15.05 0 006.59 6.59l2.2-2.2a1 1 0 011.05-.24 11.36 11.36 0 003.57.57 1 1 0 011 1V19a2 2 0 01-2 2A16 16 0 013 5a2 2 0 012-2h2.5a1 1 0 011 1 11.36 11.36 0 00.57 3.57 1 1 0 01-.24 1.05l-2.2 2.2z" />
</svg>
        </div>
      </div>
    </Router>
  );
}

export default App;
