import React, { createContext, useState, useEffect } from 'react';

// Create the Cart Context
export const CartContext = createContext();

// Provide the Cart Context
export const CartProvider = ({ children }) => {
    const [cart, setCart] = useState(() => {
        const savedCart = localStorage.getItem('cart');
        return savedCart ? JSON.parse(savedCart) : {};
    });

    const [totalItemCount, setTotalItemCount] = useState(0);
    const [totalPrice, setTotalPrice] = useState("");

    // Update localStorage and total item count whenever the cart changes
    useEffect(() => {
        localStorage.setItem('cart', JSON.stringify(cart)); // Persist the cart in localStorage
        setTotalItemCount(getTotalItemCount()); // Calculate and set the total item count
        setTotalPrice(getTotalPrice()); // Calculate and set the total price
    }, [cart]);

    const addToCart = (item) => {
        if (!item || !item.name || !item.price) return; // Check if the item is valid before proceeding
    
        setCart((prevCart) => {
            const newCart = { ...prevCart };
            if (newCart[item.name]) {
                // Ensure that the quantity is valid
                newCart[item.name].quantity = newCart[item.name].quantity ? newCart[item.name].quantity + 1 : 1;
            } else {
                newCart[item.name] = { ...item, quantity: 1 }; // Initialize quantity if it's a new item
            }
            return newCart;
        });
    };
    

    const removeFromCart = (itemName) => {
        setCart((prevCart) => {
            // Make a copy of the previous cart state
            const newCart = { ...prevCart };
    
            // Ensure the item exists in the cart and has a valid structure
            if (newCart[itemName] && newCart[itemName].quantity) {
                if (newCart[itemName].quantity > 1) {
                    // Decrease the quantity if there's more than one
                    newCart[itemName].quantity -= 1;
                } else {
                    // Remove the item from the cart if the quantity is 1
                    delete newCart[itemName];
                }
            }
    
            return newCart; // Return the updated cart
        });
    };
    //Clear Cart After Sucessfull Order Placement
    const clearCart = () => {
        setCart({});
        localStorage.removeItem('cart'); // Remove the cart from localStorage
        setTotalItemCount(0); // Reset the total item count
      };

    const getTotalPrice = () => {
        // Filter and reduce over valid cart items
        return Object.values(cart)
            .filter(item => item && item.quantity && item.price) // Filter out invalid items
            .reduce((total, item) => {
                const itemPrice = parseFloat(item.price.replace('€', '').replace(',', '.'));
                return total + item.quantity * itemPrice;
            }, 0)
            .toFixed(2);
    };

    const getTotalItemCount = () => {
        return Object.values(cart)
            .filter(item => item && item.quantity) // Filter out any null or undefined items
            .reduce((total, item) => total + item.quantity, 0); // Safely access the quantity
    };

    return (
        <CartContext.Provider value={{ cart, addToCart, removeFromCart, getTotalPrice, getTotalItemCount, totalItemCount,clearCart,totalPrice }}>
            {children}
        </CartContext.Provider>
    );
};
