import React, { useState, useEffect } from 'react';
import { auth, db } from '../FirebaseConfig';
import { doc, getDoc, updateDoc,query,where,collection,getDocs } from 'firebase/firestore';
import { signOut } from 'firebase/auth';
import '../styles/panel.css';
import loger from "../icons/loger.png";
import packager from "../icons/package.png";
import logout from "../icons/logout.png";

export default function UserPanel({ userName, userEmail, userPhone, userAddress }) {
  const [user, setUser] = useState(null);
  const [userData, setUserData] = useState({ address: userAddress, phone: userPhone, name: userName,email:userEmail });
  const [isEditing, setIsEditing] = useState(false);
  const [feedback, setFeedback] = useState([]);
  const [message, setMessage] = useState('');
  const [selectedSection, setSelectedSection] = useState('userInfo'); // State to manage the selected panel
  const [orders, setOrders] = useState([]); // Orders state
  const [Bearbeitung, setBearbeitung] = useState([]); //Bearbeitung state

  useEffect(() => {
    const fetchUserData = async () => {
      const currentUser = auth.currentUser;
      if (currentUser) {
        const docRef = doc(db, 'users', currentUser.uid);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
          setUser(currentUser);
          setUserData(docSnap.data());
        }
      }
    };
    fetchUserData();
  }, []);

  // Fetch orders (this should come from your Firebase DB where orders are stored)
  useEffect(() => {
    //Orders Collection
    const fetchOrders = async () => {
      const currentUser = auth.currentUser;
      if (currentUser) {
        try {
          // Query the 'orders' collection where the email matches the authenticated user's email
          const q = query(collection(db, 'orders'), where('email', '==', currentUser.email));
          const querySnapshot = await getDocs(q);
          if (!querySnapshot.empty) {
            const ordersData = querySnapshot.docs.map((doc) => doc.data()); // Extract data from each document
            setOrders(ordersData);
          } else {
            console.log('No matching orders found.');
          }
        } catch (error) {
          console.error('Error fetching orders:', error);
        }
      }
    };
    const fetchBearbeitung = async () => {
      const currentUser = auth.currentUser;
      if (currentUser) {
        try {
          // Query the 'Bearbeitung' collection where the email matches the authenticated user's email
          const q = query(collection(db, 'Bearbeitung'), where('email', '==', currentUser.email));
          const querySnapshot = await getDocs(q);
    
          if (!querySnapshot.empty) {
            // Assuming 'Bearbeitung' is a field in each document, and you want to aggregate results
            const bearbeitungData = querySnapshot.docs.flatMap((doc) => doc.data().Bearbeitung || []);
            setBearbeitung(bearbeitungData);
          } else {
            console.log('No matching Bearbeitung data found.');
          }
        } catch (error) {
          console.error('Error fetching Bearbeitung data:', error);
        }
      }
    };
    fetchBearbeitung();
    fetchOrders();
  }, [orders,Bearbeitung]);
    //Validate the User Address
    
    
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setUserData({ ...userData, [name]: value });
  };

  const handleSave = async () => {
    if (user) {
      const docRef = doc(db, 'users', user.uid);
      await updateDoc(docRef, {
        name: userData.name ??'',
        address: userData.address??'',
        phone: userData.phone??'',
        email: userData.email??'',
      });
      setMessage('Information updated successfully!');
      setIsEditing(false);
    }
    alert(message);
  };

  const handleLogout = async () => {
    await signOut(auth);
    window.location.reload(); // Reload the page after logout
  };

  // Rendering order status with states: received, on the way, done
  const renderOrders = () => {
    return (
      <div className="order-status">
        <h3>Your Orders</h3>
        {orders.length > 0 ? (
          <ul>
            {orders.map((order, index) => (
              <li key={index}>
                <p><strong>Order ID:</strong> {order.id}</p>
                <p><strong>Status:</strong> {order.status}</p>
                <p><strong>Estimated Arrival:</strong> {order.arrivalTime ? order.arrivalTime : 'Pending'}</p>
                {order.status === 'received' && <p>Status: Received</p>}
                {order.status === 'onTheWay' && <p>Status: On the way (Expected: {order.arrivalTime})</p>}
                {order.status === 'done' && <p>Status: Delivered</p>}
              </li>
            ))}
          </ul>
        ) : (
          <p>No orders found.</p>
        )}
      </div>
    );
  };

  // Sidebar for navigation between sections
  const renderSidebar = () => {
    return (
      <div className="sidebar">
        <button onClick={() => setSelectedSection('userInfo')}><img src={loger} alt=""/>user</button>
        <button onClick={() => setSelectedSection('orders')}><img src={packager} alt=""/> Order Status</button>
        <button onClick={handleLogout}><img src={logout} alt=""/>Logout</button>
      </div>
    );
  };

  return (
    <div className="user-panel-container" style={{ display: 'flex' }}>
      {/* Sidebar */}
      {renderSidebar()}

      {/* Content Area */}
      <div className="content-area" style={{ marginLeft: '20px', flexGrow: 1 }}>
        {selectedSection === 'userInfo' && (
          <div className="user-info">
            <h2 className="toper">Welcome, {userData.name}</h2>
            {isEditing ? (
              <div className="edit-form">
                <div>
                  <label>Name</label>
                  <input
                    type="text"
                    name="name"
                    value={userData.name}
                    onChange={handleInputChange}
                    required
                    />
                </div>
                <div>
                  <label>Address</label>
                  <input
                    type="text"
                    name="address"
                    value={userData.address || 'Address not set'}
                    onChange={handleInputChange}
                    required
                  />
                </div>
                <div>
                  <label>Phone</label>
                  <input
                    type="number"
                    name="phone"
                    value={userData.phone || 'Phone not set'}
                    onChange={handleInputChange}
                    required
                  />
                </div>
                <div>
                  <label>Email</label>
                  <input
                    type="text"
                    name="email"
                    value={userData.email||'Email not set'}
                    onChange={handleInputChange}
                    required
                  />
                </div>
                <button className='abbruch' onClick={()=>setIsEditing(false)}>Abbrechen</button>
                <button className='save' onClick={handleSave}>Save</button>
              </div>
            ) : (
              <div>
                <p><strong translate='yes'>Name</strong>  {userData.name}</p>
                <p><strong translate='yes'>Address</strong>  {userData.address}</p>
                <p><strong translate='yes'>Phone</strong>  {userData.phone}</p>
                <p><strong translate='yes'>E-Mail</strong>  {userData.email}</p>
                <button className='edit' onClick={() => setIsEditing(true)}>Edit</button>
              </div>
            )}
          </div>
        )}

        {selectedSection === 'orders' && renderOrders()}
      </div>
    </div>
  );
}
