import React, { useState, useEffect ,createContext} from "react";
import { auth, db } from '../FirebaseConfig';
import {
  GoogleAuthProvider,
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
  sendPasswordResetEmail,
  signInWithPopup,
  onAuthStateChanged,  // Import to check user state
} from 'firebase/auth';
import { setDoc, doc,getDoc } from 'firebase/firestore';
import '../styles/users.css';  // Custom CSS
import UserPanel from './UserPanel';  // Importing the UserPanel component
//import AddressValidator from './AddressValidation';  // Importing the AddressValidator component

export const User=createContext();

export default function UserProvider() {
  const [isRegistering, setIsRegistering] = useState(false);
  const [isResettingPassword, setIsResettingPassword] = useState(false);  // State for password reset
  const [isAuthenticated, setIsAuthenticated] = useState(false);  // State to track login/register success
  const [userDetails, setUserDetails] = useState({
    name: '',
    email: '',
    password: '',
    address: '',
    phone: ''
  });
  const [error, setError] = useState('');

  // Check for existing user authentication status when the component mounts
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        // User is already logged in
        setIsAuthenticated(true);
      } else {
        // No user is signed in
        setIsAuthenticated(false);
      }
    });

    // Cleanup subscription on component unmount
    return () => unsubscribe();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setUserDetails({ ...userDetails, [name]: value });
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, userDetails.email, userDetails.password);
      const user = userCredential.user;
      await setDoc(doc(db, "users", user.uid), {
        name: userDetails.name,
        email: userDetails.email,
        address: userDetails.address,
        phone: userDetails.phone,
        createdAt: new Date(),
      });
      setIsAuthenticated(true);  // Set the user as authenticated after successful registration
    } catch (error) {
      setError("Error: " + error.message);
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      await signInWithEmailAndPassword(auth, userDetails.email, userDetails.password);
      setIsAuthenticated(true);  // Set the user as authenticated after successful login
    } catch (error) {
      setError("Email or Password is incorrect");
    }
  };

  const handlePasswordReset = async (e) => {
    e.preventDefault();
    try {
      await sendPasswordResetEmail(auth, userDetails.email);
      alert('Password reset link sent to your email!');
    } catch (error) {
      setError("Error: " + error.message);
    }
  };

  const handleGoogleLogin = async () => {
    try {
      // Initialize the Google Auth provider and add the email scope
      const googleProvider = new GoogleAuthProvider();
      googleProvider.addScope('email');  // Request email explicitly
  
      // Trigger the Google Sign-In with popup
      const result = await signInWithPopup(auth, googleProvider);
      const user = result.user;
  
      // Extract email and name from user or providerData
      let email = user.email || (user.providerData.length > 0 && user.providerData[0].email);
      let name = user.displayName || (user.providerData.length > 0 && user.providerData[0].displayName);
  
      // Fallback to prompt user for email if email is null
      if (!email) {
        email = prompt('Google did not provide an email address. Please enter your email:');
      }
  
      // Check if the user exists in Firestore
      const userRef = doc(db, "users", user.uid);
      const docSnap = await getDoc(userRef);
  
      if (!docSnap.exists()) {
        // User does not exist in Firestore, save their data
        await setDoc(userRef, {
          name: name??'',
          email: email,
          createdAt: new Date(),
          phone: '',  // Empty phone by default, you can add a field for user to update this
          address: '',  // Empty address by default
        });
      }
  
      // Update the local state with the user details
      setUserDetails({
        name: name??'',
        email: email,
        password: '',  // Don't set the password
        phone: '',
        address: ''
      });
  
      setIsAuthenticated(true);  // Set the user as authenticated
      alert('Logged in successfully with Google!');
    } catch (error) {
      console.error('Error during Google login:', error);
      setError("Error during Google login: " + error.message);
    }
  };
  
  



  return (
    <div className="auth-container">
      {isAuthenticated ? ( // If the user is authenticated, show the UserPanel component
        <UserPanel userName={userDetails.name} userEmail={userDetails.email} userAddress={userDetails.address} userPhone={userDetails.phone} />
      ) : (
        !isResettingPassword ? (
          <>
            <h2>{isRegistering ? 'Register' : 'Login'}</h2>
            <form className="sign" onSubmit={isRegistering ? handleRegister : handleLogin}>
              {isRegistering && (
                <>
                  <div>
                    <label>Name</label>
                    <input
                      type="text"
                      name="name"
                      value={userDetails.name}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div>
                    <label>Address</label>
                    <input
                      type="text"
                      name="address"
                      value={userDetails.address}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div>
                    <label>Phone</label>
                    <input
                      type="tel"
                      name="phone"
                      value={userDetails.phone}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                </>
              )}
              <div className="infos">
                <label className="mail">Email</label>
                <input
                  type="email"
                  name="email"
                  value={userDetails.email}
                  onChange={handleInputChange}
                  autoComplete="email"
                  required
                />
              </div>
              <div className="infos">
                <label>Password</label>
                <input
                  type="password"
                  name="password"
                  value={userDetails.password}
                  onChange={handleInputChange}
                  autoComplete="new-password"
                  required
                />
              </div>
              {error && <p style={{ color: 'red' }}>{error}</p>}
              <button type="submit">{isRegistering ? 'Register' : 'Login'}</button>
              <button className="hider" onClick={handleGoogleLogin}>
                <img className="icon" src="https://cdn-icons-png.flaticon.com/512/281/281764.png" alt="Google Icon" />
                Login with Google
              </button>
            </form>
            <p onClick={() => setIsRegistering(!isRegistering)}>
              {isRegistering ? 'Already have an account? Login' : 'New user? Register here'}
            </p>
          </>
        ) : (
          <>
            <h2>Reset Password</h2>
            <form className="sign" onSubmit={handlePasswordReset}>
              <div className="infos">
                <label className="mail">Email</label>
                <input
                  type="email"
                  name="email"
                  value={userDetails.email}
                  onChange={handleInputChange}
                  required
                />
              </div>
              {error && <p style={{ color: 'red' }}>{error}</p>}
              <button type="submit">Send Reset Link</button>
            </form>
            <p onClick={() => setIsResettingPassword(false)}>Back to Login</p>
          </>
        )
      )}
    </div>
  );
}
